pub fn ones_like<T>(a: &Vec<T>) -> Vec<i32> {
    let n: usize = a.len();
    let mut result: Vec<i32> = Vec::with_capacity(n);

    // Invariants intended during the loop:
    // - 0 <= i <= n
    // - result.len() == i
    // - all elements in result are 1
    // Variant (termination measure): n - i, decreases each iteration.
    let mut i: usize = 0;
    while i < n {
        result.push(1);
        i += 1;
    }

    result
}

